python3 - <<'EOF'
from rdkit import Chem
smis = [
 "C[Si](C)(C)[N-]([Si](C)(C)C)->[Fe]",
 "C[Si](C)(C)N([Si](C)(C)C)->[Fe]",
]
for s in smis:
    m = Chem.MolFromSmiles(s)
    print(s, m)
    if m:
        for b in m.GetBonds():
            print(b.GetBeginAtom().GetSymbol(), b.GetEndAtom().GetSymbol(), b.GetBondType())
EOF
